package com.bank.order.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.time.LocalDateTime;

@Entity
@Table(name = "trade_orders")
public class TradeOrder {

    @Id
    @Column(name = "order_id")
    private String orderId;

    @Column(name = "account_id", nullable = false)
    private String accountId;

    @Column(nullable = false)
    private String symbol;

    @Column(nullable = false)
    private String side;

    @Column(nullable = false)
    private int quantity;

    @Column(nullable = false)
    private BigDecimal price;

    @Enumerated(EnumType.STRING)
    @Column(nullable = false)
    private OrderStatus status;

    @Column(name = "shard_key", nullable = false)
    private int shardKey;

    @Column(name = "created_at")
    private LocalDateTime createdAt;

    protected TradeOrder() {}

    public TradeOrder(String orderId, String accountId, String symbol, String side,
                       int quantity, BigDecimal price, int shardKey) {
        this.orderId = orderId;
        this.accountId = accountId;
        this.symbol = symbol;
        this.side = side;
        this.quantity = quantity;
        this.price = price;
        this.shardKey = shardKey;
        this.status = OrderStatus.PENDING;
        this.createdAt = LocalDateTime.now();
    }

    public void transition(OrderStatus newStatus) { this.status = newStatus; }

    public String getOrderId() { return orderId; }
    public String getAccountId() { return accountId; }
    public OrderStatus getStatus() { return status; }
    public int getShardKey() { return shardKey; }
}
