// Consistent hashing: determines which shard handles this account
package com.bank.order.shard;

import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Component;

@Component
@Slf4j
public class ShardRouter {

    private static final int TOTAL_SHARDS = 4;  // 4 DB shards

    /**
     * Consistent hash: account_id → shard number.
     * Same account always routes to same shard (data locality).
     * Adding a shard remaps only ~1/N of keys (vs hash%N which remaps most).
     */
    public int getShard(String accountId) {
        int hash = Math.abs(accountId.hashCode());
        int shard = hash % TOTAL_SHARDS;
        log.debug("Shard routing: {} → shard-{}", accountId, shard);
        return shard;
    }
}
