// Writes event in SAME transaction as domain change — no dual-write
package com.bank.order.service;

import com.bank.order.model.OutboxEvent;
import com.bank.order.repository.OutboxRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
@Slf4j
public class OutboxEventService {

    private final OutboxRepository outboxRepo;
    private final KafkaTemplate<String, Object> kafkaTemplate;

    // Called WITHIN an existing @Transactional — writes event in SAME TX
    public void writeEvent(String aggregateType, String aggregateId,
                            String eventType, String payload) {
        outboxRepo.save(new OutboxEvent(aggregateType, aggregateId, eventType, payload));
    }

    // Relay: polls outbox table and publishes to Kafka (runs every 5s)
    // In production: use Debezium CDC instead of polling for lower latency
    @Scheduled(fixedDelay = 5000)
    @Transactional
    public void publishPendingEvents() {
        var events = outboxRepo.findByPublishedFalseOrderByCreatedAtAsc();
        for (OutboxEvent event : events) {
            kafkaTemplate.send("order-events", event.getPayload());
            event.markPublished();
            outboxRepo.save(event);
            log.debug("Outbox relay: published event {}", event.getId());
        }
        if (!events.isEmpty()) log.info("Outbox relay: published {} events", events.size());
    }
}
