// Saga orchestrator: manages multi-step order workflow
package com.bank.order.service;

import com.bank.order.dto.*;
import com.bank.order.model.*;
import com.bank.order.repository.OrderRepository;
import com.bank.order.shard.ShardRouter;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.UUID;

@Service
@RequiredArgsConstructor
@Slf4j
public class OrderOrchestrator {

    private final OrderRepository orderRepo;
    private final OutboxEventService outboxService;
    private final ShardRouter shardRouter;

    @Transactional
    public OrderResponse placeOrder(OrderRequest request) {
        String orderId = "ORD-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase();
        int shard = shardRouter.getShard(request.accountId());

        TradeOrder order = new TradeOrder(orderId, request.accountId(), request.symbol(),
            request.side(), request.quantity(), request.price(), shard);

        // Saga step 1: validate
        order.transition(OrderStatus.VALIDATED);
        orderRepo.save(order);

        // Outbox: write event in SAME transaction as order save
        // No dual-write: both committed or both rolled back
        outboxService.writeEvent("TradeOrder", orderId, "ORDER_PLACED",
            "{\"orderId\":\"" + orderId + "\",\"symbol\":\"" + request.symbol()
            + "\",\"side\":\"" + request.side() + "\",\"quantity\":" + request.quantity()
            + ",\"price\":" + request.price() + ",\"shard\":" + shard + "}");

        log.info("Order {} placed on shard-{} → outbox event written (same TX)", orderId, shard);
        return OrderResponse.from(order);
    }
}
